{
  "case_id": "xsu_sg_014_occupational_injury_opinion",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret angiver korrekt, at udtalelsen er vejledende og ikke binder Udbetaling Danmark, og at den bygger på sagens dokumentation uden undersøgelse. Det udelader dog det andet kritiske element, nemlig om funktionsevnen er så nedsat, at et studiejob ikke kan varetages. Desuden tilføjer det, at Udbetaling Danmark kan fravige udtalelsen, hvis den samlede dokumentation peger anden vej, og at AES' opgave er at belyse evne til at påtage sig erhvervsarbejde. Det er upræcist i forhold til kilden, som taler om evne til at arbejde og studiejob."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det første kritiske element (hvor meget funktionsnedsættelsen påvirker evnen til at arbejde) dækkes i generel form. Det andet kritiske element (om funktionsevnen er så nedsat, at et studiejob ikke kan have) nævnes slet ikke."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler begge dele af spørgsmålet: hvad udtalelsen skal belyse, og om Udbetaling Danmark er bundet. Indholdet af 'belyse'-delen er mangelfuldt, men svaret er relevant og erstatter ikke et svar med irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Udsagnene henføres til en identificerbar kilde, Vejledning nr. 10157 (VEJ nr. 10157 af 05/10/2026), med citater, selvom afsnitsnummeret ikke angives."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "Vejledning nr. 10157 findes i den frosne kildeafgrænsning, er autoritativ og anvendelig. Afsnit 5.1.3.3 handler netop om AES-udtalelsen."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Citaterne understøtter, at udtalelsen er vejledende, ikke kan påklages og ikke er bindende, og at den bygger på dokumentation. Udsagnet om, at Udbetaling Danmark kan fravige udtalelsen, hvis den samlede dokumentation peger anden vej, har ikke direkte støtte i passagen. Det samme gælder, at udtalelsen skal belyse 'evne til at påtage sig erhvervsarbejde'. Henvisning 3 om 'meget betydelige begrænsninger' er heller ikke knyttet til AES-udtalelsens indhold. Et enkelt citat om 'skal belyse arbejdsevnen' fremhæver ikke studiejob-vurderingen."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at Udbetaling Danmark 'skal inddrage udtalelsen' og 'kan fravige' den, hvis dokumentationen peger anden vej, samt at udtalelsen kun skal inddrages 'som et vejledende moment'. Dele af dette er en fortolkning. Kilden siger blot, at udtalelsen indgår i vurderingen, men ikke er bindende."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Den krævede kvalifikation er bevaret: udtalelsen er vejledende, og Udbetaling Danmark er ikke bundet af den. Det fremgår også, at den ikke kan påklages."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Argumentationen er intern sammenhængende. Udtalelsen er vejledende, indgår i vurderingen, og Udbetaling Danmark er ikke bundet. Konklusionen følger af disse trin."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Modaliteten 'kan anmode' og 'vejledende' gengives korrekt. 'Udbetaling Danmark skal inddrage udtalelsen' er dog stærkere end kilden ('indgår i vurderingen'), og AES' vurdering formuleres som 'skal belyse evne til erhvervsarbejde' i stedet for den konkrete vurdering af arbejdsevne og studiejob. Det er upræcist."
    }
  },
  "xhaile_coverage": {
    "A68": {
      "label": "partial",
      "reason": "Svaret dækker, at Udbetaling Danmark kan anmode om en vejledende udtalelse om evnen til at arbejde, og at den bygger på foreliggende dokumentation uden undersøgelse. Det udelader vurderingen af, om funktionsevnen er så nedsat, at et studiejob ikke kan varetages, og at Udbetaling Danmark betaler udgifterne."
    }
  },
  "overall_notes": "Svaret er korrekt på de vejledende og ikke-bindende elementer samt på dokumentationsgrundlaget, men udelader studiejob-kriteriet, som er et kritisk element. Det tilføjer også enkelte ikke understøttede formuleringer: 'skal inddrage', 'kan fravige' og 'evne til at påtage sig erhvervsarbejde'. Kilden er identificerbar og gyldig."
}

